DO $$ BEGIN IF NOT (EXISTS(SELECT 1 FROM pg_catalog.pg_constraint WHERE conrelid='truss.source_epoch_registry'::pg_catalog.regclass AND conname='source_epoch_registry_transition_reason_check' AND pg_catalog.pg_get_constraintdef(oid)='CHECK ((transition_reason = ANY (ARRAY[''initial''::text, ''restore''::text])))') AND EXISTS(SELECT 1 FROM pg_catalog.pg_constraint WHERE conrelid='truss.source_epoch_registry'::pg_catalog.regclass AND conname='source_epoch_registry_check' AND pg_catalog.pg_get_constraintdef(oid)='CHECK ((((transition_reason = ''initial''::text) AND (predecessor_epoch IS NULL)) OR ((transition_reason = ''restore''::text) AND (predecessor_epoch IS NOT NULL))))')) THEN RAISE EXCEPTION 'original epoch reason constraints required' USING ERRCODE='55000'; END IF; END; $$; ALTER TABLE truss.source_epoch_registry DROP CONSTRAINT source_epoch_registry_transition_reason_check, DROP CONSTRAINT source_epoch_registry_check, ADD CONSTRAINT source_epoch_registry_transition_reason_check CHECK (transition_reason IN ('initial', 'restore', 'authority-change')), ADD CONSTRAINT source_epoch_registry_check CHECK ((transition_reason = 'initial' AND predecessor_epoch IS NULL) OR (transition_reason IN ('restore', 'authority-change') AND predecessor_epoch IS NOT NULL))